// Quién recibe qué, según lo que pasó en el CRM. Las direcciones se revisan después, en "Destino seguro".
// Solo se llega aquí si esta ejecución obtuvo la reserva de los avisos en el CRM (salen una sola vez).
// Se llama con un lead a la vez (lo hacen 01 y 01b)
const avisos = [];
{
  const lead = $('Cuando lo llamen').first().json;
  const r = lead.respuesta;
  const { cuerpo, correo_gerente } = lead;
  if (!r?.resultado || !r.asesor) return [];
  // "Ya procesado": el CRM lo guardó en un intento anterior, pero sus avisos no salieron. Se avisa igual
  const resultado = r.resultado === 'ya_procesado' ? r.resultado_original : r.resultado;
  if (!['creado', 'existente', 'revision'].includes(resultado)) return [];

  // Los datos ya limpios que devuelve el CRM (nombre con mayúsculas, ciudad bien escrita)
  const c = { ...cuerpo, ...(r.contacto ?? {}) };
  // Un negocio sin nombre de persona trae el nombre del negocio en los dos campos: no se repite
  const soloEmpresa = Boolean(c.empresa) && c.nombre === c.empresa;
  const nombre = c.empresa && !soloEmpresa ? `${c.nombre} (${c.empresa})` : c.empresa || c.nombre;
  // En "revisión" sin lead nuevo, el código es el del contacto que ya tiene ese celular, no el de esta persona
  const codigo = resultado === 'revision' && r.nuevo === false
    ? `Contacto con el mismo celular: ${r.codigo}`
    : `Código en el CRM: ${r.codigo}`;
  const ficha = [
    `Cliente: ${nombre}`,
    codigo,
    `Celular: ${c.telefono ?? c.celular}`,
    `Ciudad: ${c.ciudad}`,
    `Consumo: ${cuerpo.consumo ? cuerpo.consumo + ' kWh/mes' : 'no lo dijo'}`,
    `Mensaje: ${cuerpo.mensaje || '(sin mensaje)'}`,
  ].join('\n');

  // Lo que la gerente tiene que decidir
  const motivos = [];
  if (resultado === 'revision') motivos.push(`Posible duplicado: ${r.duda ?? 'revisa la nota que quedó en el contacto'}`);
  if (r.asesor_inactivo) motivos.push('El asesor del cliente ya no está activo: hay que reasignarlo');
  if (r.fuera_de_ciudad) motivos.push(`No hay asesor activo en ${c.ciudad}: se asignó a ${r.asesor.nombre}`);
  // Si quien atiende es la gerente (el asesor ya no está), los motivos van en su mismo aviso
  const atiendeLaGerente = Boolean(correo_gerente) && correo_gerente === r.asesor.email;

  // 1. Bienvenida al lead (si dejó correo). Un cliente que vuelve no la recibe otra vez
  if (resultado !== 'existente' && cuerpo.correo) {
    avisos.push({
      para: cuerpo.correo,
      quien: nombre,
      asunto: 'Recibimos tu solicitud - SolarAndes',
      texto: `${soloEmpresa ? 'Hola:' : `Hola, ${c.nombre.split(' ')[0]}:`}\n\nGracias por escribirnos. ${r.asesor.nombre} te contactará pronto para hablar de tu sistema solar.\n\nSolarAndes S.A.S.`,
    });
  }

  // 2. Aviso a quien atiende (el asesor, o la gerente si el asesor ya no está activo)
  const titulo = {
    creado: `Nuevo lead para ti: ${nombre}`,
    revision: `Nuevo lead (revisa si es un duplicado): ${nombre}`,
    existente: `Tu cliente ${nombre} volvió a escribir`,
  }[resultado];
  const decidir = atiendeLaGerente && motivos.length ? `${motivos.join('\n')}\n\n` : '';
  avisos.push({
    para: r.asesor.email,
    quien: r.asesor.nombre,
    asunto: titulo,
    texto: `${titulo}\n\n${decidir}${ficha}\n\nTienes una tarea en el CRM para contactarlo.`,
  });

  // 3. Aviso aparte a la gerente cuando hay algo que decidir y no es ella quien atiende
  if (motivos.length && correo_gerente && !atiendeLaGerente) {
    avisos.push({
      para: correo_gerente,
      quien: 'Laura Méndez',
      asunto: `Revisar lead ${r.codigo}: ${nombre}`,
      texto: `${motivos.join('\n')}\n\n${ficha}`,
    });
  }
}
return avisos.map((a) => ({ json: a }));

// Ningún mensaje real sale hacia el set de datos: solo a los correos de la tabla destinos_prueba.
// Lo demás (por ejemplo, los correos @solarandes.test del equipo) se desvía al correo de prueba.
const filas = $('Leer destinos').all().map((i) => i.json);
const correos = filas.filter((f) => f.tipo === 'correo' && f.valor).map((f) => String(f.valor).trim().toLowerCase());
const remitente = filas.find((f) => f.tipo === 'remitente' && f.valor)?.valor;
if (!correos.length || !remitente) throw new Error('Destino seguro: faltan las filas correo y remitente en destinos_prueba');

return $input.all().map(({ json: a }) => {
  const para = String(a.para ?? '').trim().toLowerCase();
  const permitido = correos.includes(para);
  return {
    json: {
      remitente,
      para: permitido ? para : correos[0],
      asunto: permitido ? a.asunto : `[Prueba: era para ${a.quien} <${para}>] ${a.asunto}`,
      texto: a.texto,
      desviado: !permitido,
    },
  };
});
